// @pit: {"label": "Squash-merge #75, tag the merge commit v2.5.0, and push the tag"}
async ({ shell: { execFile } }) => {
  const r = (a: string[]) => execFile(a[0], a.slice(1), { raise: true, timeoutMs: 40000 });
  await r(["gh", "pr", "merge", "75", "--squash", "--delete-branch"]);
  await r(["git", "switch", "main"]);
  await r(["git", "pull", "--ff-only", "origin", "main"]);
  const head = (await r(["git", "log", "--oneline", "-1"])).stdout;
  const ver = (await r(["node", "-p", "require('./package.json').version"])).stdout.trim();
  if (ver !== "2.5.0" || !head.includes("chore: release 2.5.0")) return { stop: true, head, ver };
  await r(["git", "tag", "-a", "v2.5.0", "-m", "v2.5.0"]);
  const p = await r(["git", "push", "origin", "v2.5.0"]);
  return { head, push: p.stderr.slice(-200) };
}
